#[test]
fn note_quotes_comments_and_unicode_preserve_complete_text_ir() {
 complete("double","wardley-beta\nnote \"Decision\" [0.5, 0.5]\n",expected(theme(),vec![WardleyNote{text:"Decision".into(),visibility:0.5,evolution:0.5}]));
 complete("single","wardley-beta\nnote 'Decision' [0.5, 0.5]\n",expected(theme(),vec![WardleyNote{text:"Decision".into(),visibility:0.5,evolution:0.5}]));
 complete("empty","wardley-beta\nnote \"\" [0,1]\n",expected(theme(),vec![WardleyNote{text:"".into(),visibility:0.0,evolution:1.0}]));
 complete("interior-spaces","wardley-beta\nnote \" A \" [1,0]\n",expected(theme(),vec![WardleyNote{text:" A ".into(),visibility:1.0,evolution:0.0}]));
 complete("percent-inside","wardley-beta\nnote \"50%% complete\" [0.5,0.5]\n",expected(theme(),vec![WardleyNote{text:"50%% complete".into(),visibility:0.5,evolution:0.5}]));
 complete("outside-comment","wardley-beta\nnote \"A\" [0,1] %% comment\n",expected(theme(),vec![WardleyNote{text:"A".into(),visibility:0.0,evolution:1.0}]));
 complete("inside-and-outside","wardley-beta\nnote \"A%%B\" [1,0] %% comment\n",expected(theme(),vec![WardleyNote{text:"A%%B".into(),visibility:1.0,evolution:0.0}]));
 complete("inactive-single","wardley-beta\nnote \"A'B\" [0.5,0]\n",expected(theme(),vec![WardleyNote{text:"A'B".into(),visibility:0.5,evolution:0.0}]));
 complete("inactive-double","wardley-beta\nnote 'A\"B' [0,0.5]\n",expected(theme(),vec![WardleyNote{text:"A\"B".into(),visibility:0.0,evolution:0.5}]));
 complete("bracket-unicode","wardley-beta\nnote \"[α]\" [1,1]\n",expected(theme(),vec![WardleyNote{text:"[α]".into(),visibility:1.0,evolution:1.0}]));
 complete("escaped-active","wardley-beta\nnote \"A\\\"B\" [0,0]\n",expected(theme(),vec![WardleyNote{text:"A\"B".into(),visibility:0.0,evolution:0.0}]));
 complete("escaped-backslash","wardley-beta\nnote \"A\\\\B\" [1,1]\n",expected(theme(),vec![WardleyNote{text:"A\\B".into(),visibility:1.0,evolution:1.0}]));
}
#[test]
fn malformed_note_text_and_coordinates_have_exact_source_errors() {
 {let e=parse_wardley("wardley-beta\nnote A [0,0]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note text must be quoted".into()),"case0");eprintln!("WARDLEY-NOTE-ERROR case0");}
 {let e=parse_wardley("wardley-beta\nnote \"A\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note text must be a complete quoted string".into()),"case1");eprintln!("WARDLEY-NOTE-ERROR case1");}
 {let e=parse_wardley("wardley-beta\nnote \"A\\q\" [0,0]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note text must be a complete quoted string".into()),"case2");eprintln!("WARDLEY-NOTE-ERROR case2");}
 {let e=parse_wardley("wardley-beta\nnote \"A\"\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note requires coordinates".into()),"case3");eprintln!("WARDLEY-NOTE-ERROR case3");}
 {let e=parse_wardley("wardley-beta\nnote \"A\"junk\" [0,0]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"invalid Wardley coordinates".into()),"case4");eprintln!("WARDLEY-NOTE-ERROR case4");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0,0]junk\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"invalid Wardley coordinates".into()),"case5");eprintln!("WARDLEY-NOTE-ERROR case5");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"coordinates require two values".into()),"case6");eprintln!("WARDLEY-NOTE-ERROR case6");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [x,0]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"invalid coordinate".into()),"case7");eprintln!("WARDLEY-NOTE-ERROR case7");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0,1,2]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"invalid coordinate".into()),"case8");eprintln!("WARDLEY-NOTE-ERROR case8");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [-0.1,0.5]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case9");eprintln!("WARDLEY-NOTE-ERROR case9");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0.5,-0.1]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case10");eprintln!("WARDLEY-NOTE-ERROR case10");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [1.1,0.5]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case11");eprintln!("WARDLEY-NOTE-ERROR case11");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0.5,1.1]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case12");eprintln!("WARDLEY-NOTE-ERROR case12");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [NaN,0.5]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case13");eprintln!("WARDLEY-NOTE-ERROR case13");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0.5,NaN]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case14");eprintln!("WARDLEY-NOTE-ERROR case14");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [inf,0.5]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case15");eprintln!("WARDLEY-NOTE-ERROR case15");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0.5,inf]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case16");eprintln!("WARDLEY-NOTE-ERROR case16");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [-inf,0.5]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case17");eprintln!("WARDLEY-NOTE-ERROR case17");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0.5,-inf]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case18");eprintln!("WARDLEY-NOTE-ERROR case18");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [1e309,0.5]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case19");eprintln!("WARDLEY-NOTE-ERROR case19");}
 {let e=parse_wardley("wardley-beta\nnote \"A\" [0.5,1e309]\n").unwrap_err();assert_eq!((e.line,e.col,e.message),(2,1,"Wardley note coordinates must be between 0 and 1".into()),"case20");eprintln!("WARDLEY-NOTE-ERROR case20");}
}
